leaf = "description"
rows = list(csv.DictReader(open("data/uncov_batch/" + leaf + ".tsv", encoding="utf-8-sig"), delimiter="\t"))[550:675]
assert len(rows) == len(KO), (len(rows), len(KO))
w = csv.writer(open("data/_uncov_ko_desc5.tsv", "w", encoding="utf-8", newline=""), delimiter="\t")
w.writerow(["en", "ko"])
for r, ko in zip(rows, KO):
    w.writerow([r["en"], ko])
print("desc5", len(KO))
